#include <stdio.h>
#include <stdlib.h>

#define MAX_VERTICES 9
#define MAX_EDGES 9

typedef struct { int a, b, w; } Edge;

static int find(int parent[], int x) {
    if (parent[x] != x) parent[x] = find(parent, parent[x]);
    return parent[x];
}

static int cmp_edge(const void *p1, const void *p2) {
    const Edge *e1 = (const Edge *)p1;
    const Edge *e2 = (const Edge *)p2;
    return (e1->w < e2->w) ? -1 : (e1->w > e2->w);
}

int main(int argc, char *argv[]) {
    if (argc != 2) { puts("INVALID_ARGS"); return 0; }
    char *endptr; long n = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || n < 0 || n > MAX_VERTICES) { puts("INVALID_ARGS"); return 0; }
    int vertices = (int)n;
    Edge edges[MAX_EDGES]; int edge_cnt = 0;
    while (edge_cnt < MAX_EDGES && scanf("%d %d %d", &edges[edge_cnt].a, &edges[edge_cnt].b, &edges[edge_cnt].w) == 3) edge_cnt++;
    qsort(edges, edge_cnt, sizeof(Edge), cmp_edge);
    int parent[MAX_VERTICES+1]; for (int i=0;i<=MAX_VERTICES;i++) parent[i]=i;
    int mst_edges[MAX_EDGES][2]; int mst_cnt=0; int total_weight=0;
    for (int i=0;i<edge_cnt && mst_cnt < vertices-1; ++i) {
        int a=edges[i].a, b=edges[i].b;
        if (a<0||a>MAX_VERTICES||b<0||b>MAX_VERTICES) continue;
        int pa=find(parent,a), pb=find(parent,b);
        if (pa!=pb) {
            parent[pa]=pb;
            mst_edges[mst_cnt][0]=a; mst_edges[mst_cnt][1]=b;
            total_weight+=edges[i].w; mst_cnt++;
        }
    }
    if (mst_cnt == vertices-1) {
        printf("weight=%d edges=", total_weight);
        for (int i=0;i<mst_cnt;i++) {
            printf("%d-%d", mst_edges[i][0], mst_edges[i][1]);
            putchar(',');
        }
        putchar('\n');
    } else {
        puts("DISCONNECTED");
    }
    return 0;
}
